glsl3.frag:
precision highp float;
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Drunk {
  vec4 params;
};
vec4 frag () {
  float t = params.x;
  float s = params.y;
  vec2 uv = uv0;
  uv.x += sin(uv.y * 9.0 + t * 1.7) * 0.007 * s;
  uv.y += cos(uv.x * 7.0 + t * 1.3) * 0.005 * s;
  vec2 off = vec2(sin(t * 1.1), cos(t * 0.8) * 0.6) * 0.03 * s;
  vec3 a = texture(cc_spriteTexture, uv).rgb;
  vec3 b = texture(cc_spriteTexture, uv + off).rgb;
  vec3 c = texture(cc_spriteTexture, uv - off * 0.6).rgb;
  vec3 col = mix(a, a * 0.5 + b * 0.3 + c * 0.2, clamp(s * 1.4, 0.0, 1.0));
  float edge = smoothstep(0.35, 0.85, length(uv0 - 0.5));
  col *= 1.0 - 0.35 * s * edge;
  col *= mix(vec3(1.0), vec3(1.05, 1.0, 0.9), 0.5 * s);
  return vec4(col, 1.0) * color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

