glsl3.frag:
precision highp float;
in vec2 uv0;
in vec2 worldXY;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Dusk {
  vec4 params;
  vec4 center;
  vec4 tint;
};
float bayer2 (vec2 p) {
  p = mod(p, 2.0);
  return mod(p.x * 2.0 + p.y * 3.0, 4.0);
}
float bayer4 (vec2 p) {
  return 4.0 * bayer2(p) + bayer2(floor(p / 2.0));
}
float bayer8 (vec2 p) {
  return (4.0 * bayer4(mod(p, 4.0)) + bayer2(floor(p / 4.0)) + 0.5) / 64.0;
}
vec4 frag () {
  float u = clamp((length(worldXY - center.xy) - params.z) / (params.x - params.z), 0.0, 1.0);
  float density = u * u * (3.0 - 2.0 * u);
  vec2 cell = floor(worldXY / params.w);
  if (density <= bayer8(cell)) discard;
  float a = texture(cc_spriteTexture, uv0).a * params.y;
  return vec4(tint.rgb, a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

